(root/'src/test/invoiceAtomicPhase10.test.ts').write_text('''import { describe, expect, it } from "vitest";\nimport { readFileSync } from "node:fs";\nimport { resolve } from "node:path";\n\nconst root = resolve(import.meta.dirname, "../..");\nconst read = (p: string) => readFileSync(resolve(root, p), "utf8");\n\ndescribe("Phase 10 invoice atomicity", () => {\n  it("routes manual invoice creation through the edge function", () => {\n    expect(read("src/features/billing/pages/Billing.tsx")).toContain('functions.invoke("create-invoice"');\n    expect(read("src/features/properties/components/PropertyBillingTab.tsx")).toContain('functions.invoke("create-invoice"');\n    expect(read("src/features/billing/pages/Billing.tsx")).not.toMatch(/from\\(["']invoices["']\\)[\\s\\S]{0,300}\\.insert\\(/);\n    expect(read("src/features/properties/components/PropertyBillingTab.tsx")).not.toMatch(/from\\(["']invoices["']\\)[\\s\\S]{0,300}\\.insert\\(/);\n  });\n  it("uses one service-only atomic RPC", () => {\n    const sql = read("supabase/migrations/20260902000004_atomic_invoice_creation_v2.sql");\n    expect(sql).toContain("SECURITY DEFINER");\n    expect(sql).toContain("auth.role() <> 'service_role'");\n    expect(sql).toContain("ON CONFLICT (generation_key)");\n    expect(read("supabase/functions/apply-penalties/index.ts")).toContain('rpc("create_invoice_atomic_v2"');\n  });\n});\n''')
(root/'docs/CALQULUS_INVOICE_ATOMIC_PHASE10_AUDIT.md').write_text('''# CALQULUS Phase 10 — Invoice Atomicity Audit\n\n## Scope\nConverges tenant-facing manual invoice creation, property billing invoice creation, water invoices, and late-penalty invoices onto the service-only atomic invoice RPC.\n\n## Controls\n- `create_invoice_atomic_v2` is SECURITY DEFINER and executable only by `service_role`.\n- Tenant and property manager ownership is checked inside the transaction.\n- Lease ownership is checked when a lease is supplied.\n- `generation_key` provides idempotent creation.\n- Manual clients call the authenticated `create-invoice` Edge Function; they never receive service-role credentials.\n- Water billing uses a deterministic reading-based generation key.\n- Penalties use an invoice/date generation key and no longer perform a direct invoice insert.\n\n## Verification\nStatic source audit and ZIP integrity were run for this phase. Runtime npm gates remain dependent on installed project dependencies.\n''')
